@push('scripts')<script>const cleanNumber=value=>{const number=Number(value);return Number.isFinite(number)?String(number):''};const updateAllowanceTotal=()=>document.getElementById('allowance-total').value=cleanNumber([...document.querySelectorAll('.allowance-input')].reduce((sum,input)=>sum+(parseFloat(input.value)||0),0))+'%';document.querySelectorAll('.allowance-input').forEach(input=>input.addEventListener('input',updateAllowanceTotal));updateAllowanceTotal();</script>@endpush
